const updateEvent = `-- name: UpdateEvent :one
UPDATE events
SET title = COALESCE($1, title),
    venue_id = COALESCE($2, venue_id),
    opening_time = COALESCE($3, opening_time),
    start_time = COALESCE($4, start_time),
    end_time = COALESCE($5, end_time),
    related_links = COALESCE($6, related_links),
    status = COALESCE($7, status),
    updated_at = NOW()
WHERE id = $8
RETURNING id, title, venue_id, opening_time, start_time, end_time, related_links, rating_sum, rating_count, status, author_id, created_at, updated_at
`

type UpdateEventParams struct {
	Title        sql.NullString
	VenueID      uuid.NullUUID
	OpeningTime  sql.NullTime
	StartTime    sql.NullTime
	EndTime      sql.NullTime
	RelatedLinks []string
	Status       sql.NullString
	ID           uuid.UUID
}

func (q *Queries) UpdateEvent(ctx context.Context, arg UpdateEventParams) (Event, error) {
	row := q.db.QueryRowContext(ctx, updateEvent,
		arg.Title,
		arg.VenueID,
		arg.OpeningTime,
		arg.StartTime,
		arg.EndTime,
		pq.Array(arg.RelatedLinks),
		arg.Status,
		arg.ID,
	)
	var i Event
	err := row.Scan(
		&i.ID,
		&i.Title,
		&i.VenueID,
		&i.OpeningTime,
		&i.StartTime,
		&i.EndTime,
		pq.Array(&i.RelatedLinks),
		&i.RatingSum,
		&i.RatingCount,
		&i.Status,
		&i.AuthorID,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

